INSERT INTO public.lobby_history(lobby_id,host_id,change_type,room_name,players,player_limit,is_public,observed_at,date_created) SELECT value.lobby_id,value.host_id,value.change_type,value.room_name,value.players,value.player_limit,value.is_public,$2::timestamptz,$2::timestamptz FROM jsonb_to_recordset($1) AS value(lobby_id bigint,host_id bigint,change_type text,room_name text,players integer,player_limit integer,is_public boolean)
